components-atom-link--link-default.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlLinkComponent } from '@domg-wc/components/atom';

registerWebComponents([VlLinkComponent]);

// vl-click volgt op elke klik (bubbles en composed). Het native click event werkt ook: gebruik er één van.
document.querySelector('vl-link').addEventListener('vl-click', () => {
    console.log('link geklikt');
});

components-atom-link--button-styled-as-l.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlLinkComponent } from '@domg-wc/components/atom';

registerWebComponents([VlLinkComponent]);

// Met button-as-link rendert vl-link een <button type="button"> in plaats van een <a>: de actie hang je aan vl-click.
document.querySelector('vl-link[button-as-link]').addEventListener('vl-click', () => {
    console.log('annuleren');
});
